; =============================================================================
; Final Fantasy Legend, The (U) [!].gb  (SaGa / Makai Toushi SaGa, Square 1989) - sound driver
; Bank $07 $4000-$6DF9 + ROM0 caller fragment $06D0-$06E4.  Generated by tools/gen_ffl1.py.
; Rebuilds byte-exact with RGBDS 0.9.x:
;   rgbasm -Wall -o ffl1snd.o FFL1_SoundDriver.asm
;   rgblink -o ffl1snd.gb ffl1snd.o ; python tools/cmp_ranges.py <rom> ffl1snd.gb
; =============================================================================

DEF rNR10    EQU $FF10
DEF rNR11    EQU $FF11
DEF rNR12    EQU $FF12
DEF rNR13    EQU $FF13
DEF rNR14    EQU $FF14
DEF rNR21    EQU $FF16
DEF rNR22    EQU $FF17
DEF rNR23    EQU $FF18
DEF rNR24    EQU $FF19
DEF rNR30    EQU $FF1A
DEF rNR31    EQU $FF1B
DEF rNR32    EQU $FF1C
DEF rNR33    EQU $FF1D
DEF rNR34    EQU $FF1E
DEF rNR41    EQU $FF20
DEF rNR42    EQU $FF21
DEF rNR43    EQU $FF22
DEF rNR44    EQU $FF23
DEF rNR50    EQU $FF24
DEF rNR51    EQU $FF25
DEF rNR52    EQU $FF26
DEF rIF     EQU $FF0F
DEF rLYC    EQU $FF45

DEF hSongRequest    EQU $FFE0
DEF hSongCurrent    EQU $FFE1
DEF hSpecialSong    EQU $FFE2
DEF hSpecialActive  EQU $FFE3
DEF hSfxRequest     EQU $FFE4
DEF hEvent          EQU $FFE6
DEF hChannelBase    EQU $FFE7
DEF hChannel        EQU $FFE9
DEF hTempo          EQU $FFEA
DEF hSfxTonePtr     EQU $FFEB
DEF hSfxNoisePtr    EQU $FFED

; Three channel structs of $20 bytes: CH1 $CE00, CH2 $CE20, CH3 $CE40 (saved copy at $CE60 during a special song)
;  +$00 Flags      bit 7 = stopped, bit 0 = an SFX owns the channel (CH1 only)
;  +$01 Timer      ticks until the next stream read      +$02 Ptr (2)  stream pointer
;  +$04 Event      last note/rest/tie byte read, $0F = none   +$05 Octave (0-4)   +$06 LoopCount
;  +$09 Freq (2)   period of the current note, $FFFF = rest   +$0B Volume (1-15)
;  +$0C/$0D/$0E    volume envelope id / position / timer
;  +$0F/$10/$11    pitch effect id / position / timer
;  +$12/$13/$14    duty sequence id / position / timer
;  +$15/$16/$17    pan sequence id / position / timer
;  +$18-$1B        NRx1-NRx4 copies (NRx1 only set by $F5; used to restore CH1 after an SFX)
;  +$1C            last pan byte
DEF wCh1Flags           EQU $CE00
DEF wCh1Timer           EQU $CE01
DEF wCh1Ptr             EQU $CE02
DEF wCh1Event           EQU $CE04
DEF wCh1Octave          EQU $CE05
DEF wCh1LoopCount       EQU $CE06
DEF wCh1Freq            EQU $CE09
DEF wCh1Volume          EQU $CE0B
DEF wCh1VolEnv          EQU $CE0C
DEF wCh1VolEnvPos       EQU $CE0D
DEF wCh1VolEnvTimer     EQU $CE0E
DEF wCh1Pitch           EQU $CE0F
DEF wCh1PitchPos        EQU $CE10
DEF wCh1PitchTimer      EQU $CE11
DEF wCh1Duty            EQU $CE12
DEF wCh1DutyPos         EQU $CE13
DEF wCh1DutyTimer       EQU $CE14
DEF wCh1Pan             EQU $CE15
DEF wCh1PanPos          EQU $CE16
DEF wCh1PanTimer        EQU $CE17
DEF wCh1NRx1            EQU $CE18
DEF wCh1NRx2            EQU $CE19
DEF wCh1NRx3            EQU $CE1A
DEF wCh1NRx4            EQU $CE1B
DEF wCh1PanByte         EQU $CE1C
DEF wCh2Flags           EQU $CE20
DEF wCh2Timer           EQU $CE21
DEF wCh2Ptr             EQU $CE22
DEF wCh2Event           EQU $CE24
DEF wCh2Octave          EQU $CE25
DEF wCh2LoopCount       EQU $CE26
DEF wCh2Freq            EQU $CE29
DEF wCh2Volume          EQU $CE2B
DEF wCh2VolEnv          EQU $CE2C
DEF wCh2VolEnvPos       EQU $CE2D
DEF wCh2VolEnvTimer     EQU $CE2E
DEF wCh2Pitch           EQU $CE2F
DEF wCh2PitchPos        EQU $CE30
DEF wCh2PitchTimer      EQU $CE31
DEF wCh2Duty            EQU $CE32
DEF wCh2DutyPos         EQU $CE33
DEF wCh2DutyTimer       EQU $CE34
DEF wCh2Pan             EQU $CE35
DEF wCh2PanPos          EQU $CE36
DEF wCh2PanTimer        EQU $CE37
DEF wCh2NRx1            EQU $CE38
DEF wCh2NRx2            EQU $CE39
DEF wCh2NRx3            EQU $CE3A
DEF wCh2NRx4            EQU $CE3B
DEF wCh2PanByte         EQU $CE3C
DEF wCh3Flags           EQU $CE40
DEF wCh3Timer           EQU $CE41
DEF wCh3Ptr             EQU $CE42
DEF wCh3Event           EQU $CE44
DEF wCh3Octave          EQU $CE45
DEF wCh3LoopCount       EQU $CE46
DEF wCh3Freq            EQU $CE49
DEF wCh3Volume          EQU $CE4B
DEF wCh3VolEnv          EQU $CE4C
DEF wCh3VolEnvPos       EQU $CE4D
DEF wCh3VolEnvTimer     EQU $CE4E
DEF wCh3Pitch           EQU $CE4F
DEF wCh3PitchPos        EQU $CE50
DEF wCh3PitchTimer      EQU $CE51
DEF wCh3Duty            EQU $CE52
DEF wCh3DutyPos         EQU $CE53
DEF wCh3DutyTimer       EQU $CE54
DEF wCh3Pan             EQU $CE55
DEF wCh3PanPos          EQU $CE56
DEF wCh3PanTimer        EQU $CE57
DEF wCh3NRx1            EQU $CE58
DEF wCh3NRx2            EQU $CE59
DEF wCh3NRx3            EQU $CE5A
DEF wCh3NRx4            EQU $CE5B
DEF wCh3PanByte         EQU $CE5C
DEF wSavedChannels      EQU $CE60
DEF wSavedTempo         EQU $CEC0
DEF wSavedSong          EQU $CEC1
DEF wTempoAcc           EQU $CEC2
DEF wSfxToneTimer       EQU $CEC3
DEF wSfxNoiseTimer      EQU $CEC4
DEF wSfxToneCount       EQU $CEC5
DEF wSfxNoiseCount      EQU $CEC6
DEF wSfxNoiseOn         EQU $CEC7

; ---------------------------------------------------------------- music macros
; event byte = pitch << 4 | length index;  pitch 0-B = C..B, C = rest, D = tie
DEF C_ EQU 0
DEF Cs_ EQU 1
DEF D_ EQU 2
DEF Ds_ EQU 3
DEF E_ EQU 4
DEF F_ EQU 5
DEF Fs_ EQU 6
DEF G_ EQU 7
DEF Gs_ EQU 8
DEF A_ EQU 9
DEF As_ EQU 10
DEF B_ EQU 11
DEF L96  EQU 0
DEF L72  EQU 1
DEF L48  EQU 2
DEF L36  EQU 3
DEF L32  EQU 4
DEF L24  EQU 5
DEF L18  EQU 6
DEF L16  EQU 7
DEF L12  EQU 8
DEF L9   EQU 9
DEF L8   EQU 10
DEF L6   EQU 11
DEF L4   EQU 12
DEF L3   EQU 13
DEF L2   EQU 14
DEF L44  EQU 15   ; index 15 reads NoteFreqTable's first byte ($2C); unused
DEF INS_VOL   EQU 0
DEF INS_PITCH EQU 1
DEF INS_DUTY  EQU 2
DEF INS_PAN   EQU 3
MACRO note      ; pitch, ticks
    db (\1) << 4 | L\2
ENDM
MACRO rest      ; ticks
    db $C0 | L\1
ENDM
MACRO tie       ; ticks
    db $D0 | L\1
ENDM
MACRO tempo     ; ticks per second (global)
    db $E0, \1
ENDM
MACRO volume    ; 1-15
    db $E0 | (\1)
ENDM
MACRO octave    ; 0-4
    db $F0 | (\1)
ENDM
MACRO set_nrx1  ; (unused by the songs)
    db $F5, \1
ENDM
MACRO instr     ; kind, id
    db $F7, (\1) << 6 | (\2)
ENDM
MACRO wave      ; n
    db $F8, \1
ENDM
MACRO loop_count ; 1-3
    db $F8 + (\1)
ENDM
MACRO loop      ; count 0 -> fall through, else --count and jump
    db $FC
    dw \1
ENDM
MACRO if_done   ; count 0 -> jump
    db $FD
    dw \1
ENDM
MACRO jump
    db $FE
    dw \1
ENDM
MACRO end_track
    db $FF
ENDM
; instrument sequences
MACRO env       ; ticks, level << 4 | NRx2 low nibble
    db \1, \2
ENDM
MACRO pfx       ; ticks, signed period offset
    db \1, (\2) & $FF
ENDM
MACRO seq_goto  ; position (byte offset from the sequence start)
    db 0, \1
ENDM
MACRO duty_step ; duty 0-3, ticks
    db (\1) << 6 | (\2)
ENDM
MACRO pan_step  ; right, left, ticks
    db (\1) << 7 | (\2) << 6 | (\3)
ENDM
; SFX
MACRO sfx_tone  ; frames, NR10, NR11, NR12, NR13, NR14
    db \1, \2, \3, \4, \5, \6
ENDM
MACRO sfx_noise ; frames, NR42, NR43
    db \1, \2, \3
ENDM
MACRO sfx_count ; n
    db $E0 | (\1)
ENDM
MACRO sfx_loop  ; --count != 0 -> jump
    db $F0
    dw \1
ENDM
MACRO sfx_end
    db 0
ENDM

; =============================================================================
SECTION "SoundCaller", ROM0[$06D0]
; LCD (LYC) interrupt handler fragment. rst $28 = switch ROM bank to A, returning the old one.
LcdIsrSound::
    call SoundUpdateFar
    push af
    xor a
    ldh [rLYC], a
    ldh [rIF], a
    pop af
    reti
SoundUpdateFar::                      ; continues at $06E5 with non-sound ISR work
    push af
    ld a, BANK(SoundUpdate)
    rst $28
    push af
    call SoundUpdate
    pop af
    rst $28

; =============================================================================
SECTION "Sound", ROMX[$4000], BANK[$07]

SoundInit:
    jp SoundInit_Main                 ; called once at boot ($02D5)

SoundUpdate:
    jp SoundUpdate_Main               ; called every frame from the LCD ISR ($06DB)

SoundInit_Main:
    push af
    push bc
    push de
    push hl
    ld a, $8F                         ; APU on; volumes, NR51 = 0
    ldh [rNR52], a
    xor a
    ldh [rNR10], a
    ldh [rNR12], a
    ldh [rNR22], a
    ldh [rNR32], a
    ldh [rNR42], a
    ldh [rNR51], a
    ld [hSongRequest], a
    ld [hSongCurrent], a
    dec a                             ; all three channels stopped, tempo $FF
    ld [wCh1Flags], a
    ld [wCh2Flags], a
    ld [wCh3Flags], a
    ldh [hTempo], a
    jp PopAllRet

SoundUpdate_Main:
    push af
    push bc
    push de
    push hl
    call SpecialSongUpdate            ; special-song push/pop first
    ldh a, [hTempo]
    ld e, a
    ld a, [wTempoAcc]                 ; wTempoAcc += hTempo; one tick per 60 -> tempo = ticks per second
    add a, e
.l403E:
    ld [wTempoAcc], a
    sub $3C
    jr c, SoundUpdate_Main.l404D
    call MusicTick                    ; output first (uses the event read on the previous tick), then read the streams
    call StreamTick
    jr SoundUpdate_Main.l403E
.l404D:
    call SfxUpdate                    ; SFX run once per frame, outside the tempo loop
    jp PopAllRet

CopyWord:
    ld a, [hli]
    ld [de], a
    inc de
    ld a, [hli]
    ld [de], a
    ret

StartSong:
    ld a, e                           ; hSongCurrent = id (0 = silence; no range check)
    ldh [hSongCurrent], a
    push af
    xor a
    ld c, $60                         ; clear all three channel structs
    ld hl, wCh1Flags
.l4063:
    ld [hli], a
    dec c
    jr nz, StartSong.l4063
    pop af
    ld e, a                           ; SongTable + id*6
    add a, a
    add a, e
    add a, a
    ld e, a
    ld d, $00
    ld hl, SongTable
    add hl, de
    ld de, wCh1Ptr
    call CopyWord
    ld de, wCh2Ptr
    call CopyWord
    ld de, wCh3Ptr
    call CopyWord
    ld a, $0F                         ; Event = $0F (none), Timer = 1, VolEnvTimer = PitchTimer = DutyTimer = PanTimer = 1
    ld [wCh1Event], a
    ld [wCh2Event], a
    ld [wCh3Event], a
    ld a, $01
    ld [wCh1Timer], a
    ld [wCh2Timer], a
    ld [wCh3Timer], a
    ld [wCh1VolEnvTimer], a
    ld [wCh2VolEnvTimer], a
    ld [wCh3VolEnvTimer], a
    ld [wCh1DutyTimer], a
    ld [wCh2DutyTimer], a
    ld [wCh3DutyTimer], a
    ld [wCh1PanTimer], a
    ld [wCh2PanTimer], a
    ld [wCh3PanTimer], a
    sub a                             ; Flags = 0. Note: hTempo is NOT reset (inherited from the previous song)
    ld [wCh1Flags], a
    ld [wCh2Flags], a
    ld [wCh3Flags], a
    ld a, $8F
    ldh [rNR52], a
    ld a, $FF                         ; NR30 = $FF: wave DAC on
    ldh [rNR30], a
    ld a, $77
    ldh [rNR50], a
    ret

MusicTick:
    push af
    push bc
    push de
    push hl
    ldh a, [hSongRequest]
    ld e, a
    ldh a, [hSongCurrent]
    cp e
    jr z, MusicTick.l40DC
    call StartSong                    ; song request differs -> start it
.l40DC:
    ld hl, wCh1Flags
    sub a
    bit 0, [hl]                       ; NR10 = 0 every tick unless an SFX owns CH1
    jr nz, MusicTick.l40E6
    ldh [rNR10], a
.l40E6:
    call ChannelOutput
    ld hl, wCh2Flags
    ld a, $01
    call ChannelOutput
    ld hl, wCh3Flags
    ld a, $02
    call ChannelOutput
    jp PopAllRet

ChannelOutput:
    ldh [hChannel], a
    ld a, l
    ldh [hChannelBase], a
    ld a, h
    ldh [hChannelBase+1], a
    push hl                           ; Event low nibble -> note length (also for ties/rests)
    ld de, $0004
    add hl, de
    ld a, [hl]
    ldh [hEvent], a
    cp $0F                            ; $0F = "no event this tick" (so a C with length index 15 can never play)
    jr z, ChannelOutput.l4121
    and $0F
    ld b, $00
    ld c, a
    ld hl, NoteLengthTable
    add hl, bc
    ld a, [hl]
    ld hl, $0001                      ; +$01 Timer
    call ChannelField
    ld [hl], a
.l4121:
    pop hl
    bit 7, [hl]                       ; stopped channel: nothing
    jr z, ChannelOutput.l412E
    ld de, $0004
    add hl, de
    ld a, $0F
    ld [hl], a
    ret
.l412E:
    call ProcessEvent
    jp VolumeEnvStep

ProcessEvent:
    ldh a, [hEvent]
    cp $0F
    ret z
    cp $D0                            ; $D0-$DF tie: keep everything, effects not restarted
    jp nc, ProcessEvent.l4186
    cp $C0                            ; $C0-$CF rest: Freq = $FFFF
    jp nc, ProcessEvent.l417A
    srl a                             ; pitch nibble * 2
    srl a
    srl a
    and $1E
    ld b, $00
    ld c, a
    ld hl, $0005                      ; +$05 Octave
    call ChannelField
    ld a, [hl]                        ; Octave * 24
    add a, a
    add a, a
    ld e, a
    add a, a
    add a, e
    add a, a
    ld e, a
    ld d, $00
    ld hl, NoteFreqTable
    add hl, bc
    call ReadWordAtHLDE
    ld hl, $0009                      ; +$09 Freq
    call ChannelField
    ld [hl], e
    inc hl
    ld [hl], d
    ld hl, $000D                      ; new note: restart the volume envelope
    call ChannelField
    sub a
    ld [hli], a
    ld a, $01
    ld [hl], a
    ret
.l417A:
    ld hl, $0009                      ; +$09 Freq
    call ChannelField
    ld [hl], $FF
    inc hl
    ld [hl], $FF
    ret
.l4186:
    ld a, $0F
    ldh [hEvent], a
    ret

VolumeEnvStep:
    ld hl, $000A                      ; rest: NRx2 = $08 (silent, DAC on), retrigger CH1/CH2
    call ChannelField
    ld a, [hl]
    cp $FF
    jr nz, VolumeEnvStep.l41B2
    ldh a, [hChannel]
    ld l, a
    ld h, $00
    ld de, RegNRx2
    add hl, de
    ld c, [hl]
    ld a, $08
    ldh [c], a
    ldh a, [hChannel]
    cp $02
    jp z, PanStep
    inc c
    inc c
    ld a, $80
    ldh [c], a
    jp PanStep
.l41B2:
    ld hl, $000E                      ; +$0E VolEnvTimer
    call ChannelField
    dec [hl]
    jp nz, PitchFxStep
    push hl
.l41BD:
    ld hl, $000C                      ; +$0C VolEnv
    call ChannelField
    ld a, [hl]
    add a, a
    ld l, a
    ld h, $00
    ld de, VolEnvTable
    call ReadWordAtHLDE
    ld hl, $000D                      ; +$0D VolEnvPos
    call ChannelField
    push hl
    ld a, [hl]
    inc [hl]
    inc [hl]
    ld l, a
    ld h, $00
    add hl, de
    ld a, [hli]                       ; pair: timer, value; timer 0 = jump to the position in the next byte
    pop bc
    inc bc
    ld [bc], a
    cp $00
    jr nz, VolumeEnvStep.l41E9
    ld a, [hl]
    dec bc
    ld [bc], a
    jr VolumeEnvStep.l41BD
.l41E9:
    ld a, [hl]
    pop hl
    push af
    and $F0
    swap a
    ld e, a
    dec hl
    dec hl
    dec hl
    ld a, [hl]
    ld d, a
    sub a                             ; level = (env level * Volume + 16) >> 4  (env 0 still gives level 1)
    bit 0, e
    jr z, VolumeEnvStep.l41FC
    add a, d
.l41FC:
    sla d
    bit 1, e
    jr z, VolumeEnvStep.l4203
    add a, d
.l4203:
    sla d
    bit 2, e
    jr z, VolumeEnvStep.l420A
    add a, d
.l420A:
    sla d
    bit 3, e
    jr z, VolumeEnvStep.l4211
    add a, d
.l4211:
    add a, $10
    ld hl, $0019                      ; +$19 NRx2
    call ChannelField
    ld e, a
    ldh a, [hChannel]
    cp $02                            ; CH3: level -> NR32 via Ch3VolumeTable
    jr nz, VolumeEnvStep.l4231
    ld a, e
    and $F0
    swap a
    ld e, a
    ld d, $00
    push hl
    ld hl, Ch3VolumeTable
    add hl, de
    ld a, [hl]
    pop hl
    jr VolumeEnvStep.l4234
.l4231:
    ld a, e
    and $F0
.l4234:
    ld e, a
    pop af
    and $0F
    or e
    ld [hl], a
    ldh a, [hChannel]
    ld de, RegNRx2
    add a, e
    jr nc, VolumeEnvStep.l4243
    inc d
.l4243:
    ld e, a
    ld a, [de]
    ld c, a
    call IsChannelFree                ; skipped while an SFX owns CH1
    jr nc, PitchFxStep
    ld a, [hli]
    ldh [c], a
    ldh a, [hChannel]
    cp $02
    jr z, PitchFxStep
    inc hl                            ; every envelope step retriggers CH1/CH2 (with the cached NRx4)
    ld a, [hl]
    or $80
    and $87
    inc c
    inc c
    ldh [c], a

PitchFxStep:
    ldh a, [hEvent]                   ; new note: restart pitch effect
    cp $0F
    jr z, PitchFxStep.l426D
    ld hl, $0010                      ; +$10 PitchPos
    call ChannelField
    sub a
    ld [hli], a
    ld a, $01
    ld [hl], a
.l426D:
    ld hl, $0011                      ; +$11 PitchTimer
    call ChannelField
    dec [hl]
    jp nz, DutyStep
    dec hl
    dec hl
    ld a, [hli]
    push hl
    add a, a
    ld e, a
    ld d, $00
    ld hl, PitchFxTable
    call ReadWordAtHLDE
    pop hl
    push hl
    ld a, [hl]
    inc [hl]
    inc [hl]
    ld l, a
    ld h, $00
    add hl, de
    ld a, [hli]
    push hl
    pop de
    cp $00
    jr nz, PitchFxStep.l429D
    ld a, [hl]
    pop hl
    ld [hli], a
    ld a, $01
    ld [hl], a
    jr PitchFxStep.l426D
.l429D:
    pop hl
    inc hl
    ld [hl], a
    ld hl, $0009                      ; +$09 Freq
    call ChannelField
    ld c, [hl]
    inc hl
    ld b, [hl]
    ld a, [de]                        ; Freq + signed offset; NRx3/NRx4 written only when they change (no trigger)
    bit 7, a
    jr nz, PitchFxStep.l42B3
    ld l, a
    ld h, $00
    jr PitchFxStep.l42B6
.l42B3:
    ld l, a
    ld h, $FF
.l42B6:
    add hl, bc
    push hl
    ldh a, [hChannel]
    ld e, a
    ld d, $00
    ld hl, RegNRx3
    add hl, de
    ld a, [hl]
    ld c, a
    ld hl, $001A                      ; +$1A NRx3
    call ChannelField
    pop de
    call IsChannelFree
    jr nc, DutyStep
    ld a, e
    cp [hl]
    jr z, PitchFxStep.l42D5
    ld [hl], a
    ldh [c], a
.l42D5:
    inc hl
    inc c
    ld a, d
    and $07
    cp [hl]
    jr z, DutyStep
    ld [hl], a
    ldh [c], a

DutyStep:
    ldh a, [hEvent]                   ; new note: restart duty sequence
    cp $0F
    jr z, DutyStep.l42F0
    ld hl, $0013                      ; +$13 DutyPos
    call ChannelField
    sub a
    ld [hli], a
    ld a, $01
    ld [hl], a
.l42F0:
    ld hl, $0014                      ; +$14 DutyTimer
    call ChannelField
    dec [hl]
    jr nz, PanStep
    dec hl
    dec hl
    ld a, [hli]
    push hl
    add a, a
    ld e, a
    ld d, $00
    ld hl, DutyTable
    call ReadWordAtHLDE
    pop hl
    push hl
    ld a, [hl]
    inc [hl]
    ld l, a
    ld h, $00
    add hl, de
    ld a, [hli]
    push hl
    pop de
    cp $00
    jr nz, DutyStep.l431E
    ld a, [hl]
    pop hl
    ld [hli], a
    ld a, $01
    ld [hl], a
    jr DutyStep.l42F0
.l431E:
    pop hl
    inc hl
    ld b, a                           ; byte: duty << 6 | ticks
    and $3F
    ld [hl], a
    call IsChannelFree
    jr nc, PanStep
    ldh a, [hChannel]
    ld e, a
    ld d, $00
    ld hl, RegNRx1
    add hl, de
    ld a, [hl]
    ld c, a
    ld a, b
    and $C0                           ; NRx1 = duty (CH3: lands in NR31)
    ldh [c], a

PanStep:
    ld hl, $0017                      ; pan sequence is NOT restarted by notes
    call ChannelField
    dec [hl]
    jr nz, PanStep.l4375
    dec hl
    dec hl
    ld a, [hli]
    push hl
    add a, a
    ld e, a
    ld d, $00
    ld hl, PanTable
    call ReadWordAtHLDE
    pop hl
    push hl
    ld a, [hl]
    inc [hl]
    ld l, a
    ld h, $00
    add hl, de
    ld a, [hli]
    push hl
    pop de
    cp $00
    jr nz, PanStep.l4366
    ld a, [hl]
    pop hl
    ld [hli], a
    ld a, $01
    ld [hl], a
    jr PanStep
.l4366:
    pop hl
    push af                           ; byte: R << 7 | L << 6 | ticks
    inc hl
    and $3F
    ld [hl], a
    pop af
    ld de, $0005
    add hl, de
    ld [hl], a
    call ApplyPan
.l4375:
    ld hl, $0004                      ; +$04 Event
    call ChannelField
    ld a, $0F                         ; event consumed
    ld [hl], a
    ldh [hEvent], a
    ret

ReadWordAtHLDE:
    add hl, de
    ld e, [hl]
    inc hl
    ld d, [hl]
    ret

ApplyPan:
    ldh a, [hChannel]
    cp $00
    jr z, ApplyPan.l4392
    cp $01
    jr z, ApplyPan.l43AB
    jr ApplyPan.l43BE
.l4392:
    ld a, [wCh1Flags]                 ; CH1 pan is not touched while an SFX owns CH1
    bit 0, a
    ret nz
    ld a, [hl]
    ld e, a
    sub a
    bit 7, e
    jr z, ApplyPan.l43A1
    or $10
.l43A1:
    bit 6, e
    jr z, ApplyPan.l43A7
    or $01
.l43A7:
    ld e, $EE
    jr ApplyPan.l43CF
.l43AB:
    ld a, [hl]
    ld e, a
    sub a
    bit 7, e
    jr z, ApplyPan.l43B4
    or $20
.l43B4:
    bit 6, e
    jr z, ApplyPan.l43BA
    or $02
.l43BA:
    ld e, $DD
    jr ApplyPan.l43CF
.l43BE:
    ld a, [hl]
    ld e, a
    sub a
    bit 7, e
    jr z, ApplyPan.l43C7
    or $40
.l43C7:
    bit 6, e
    jr z, ApplyPan.l43CD
    or $04
.l43CD:
    ld e, $BB
.l43CF:
    push de
    ld d, a
    ldh a, [rNR51]
    and e
    or d
    ldh [rNR51], a
    pop de
    ret

IsChannelFree:
    push hl
    ld hl, $0000                      ; +$00 Flags
    call ChannelField
    bit 0, [hl]
    jr nz, IsChannelFree.l43E7
    pop hl
    scf
    ret
.l43E7:
    pop hl
    or a
    ret

Ch3VolumeTable:
    db $00, $00, $00, $60, $60, $60, $60, $40, $40, $40, $40, $20, $20, $20, $20, $20; level 0-15 -> NR32

RegNRx3:
    db $13, $18, $1D                  ; NR13, NR23, NR33

RegNRx2:
    db $12, $17, $1C                  ; NR12, NR22, NR32

RegNRx1:
    db $11, $16, $1B                  ; NR11, NR21, NR31

NoteLengthTable:
    db $60, $48, $30, $24, $20, $18, $12, $10, $0C, $09, $08, $06, $04, $03, $02; 15 lengths (index 15 falls into NoteFreqTable: 44)

NoteFreqTable:
    ; plain periods (no trigger bit); index = octave*24 + note*2
    dw $002C, $009D, $0107, $016B, $01C9, $0223, $0277, $02C7, $0312, $0358, $039B, $03DA
    dw $0416, $044E, $0483, $04B5, $04E5, $0511, $053B, $0563, $0589, $05AC, $05CE, $05ED
    dw $060B, $0627, $0642, $065B, $0672, $0689, $069E, $06B2, $06C4, $06D6, $06E7, $06F7
    dw $0706, $0714, $0721, $072D, $0739, $0744, $074F, $0759, $0762, $076B, $0773, $077B
    dw $0783, $078A, $0790, $0797, $079D, $07A2, $07A7, $07AC, $07B1, $07B6, $07BA, $07BE
    dw $07C1, $07C5, $07C8, $07CB, $07CE, $07D1, $07D4, $07D6, $07D9, $07DB, $07DD, $07DF
    dw $07E1, $07E2, $07E4, $07E6, $07E7, $07E9, $07EA, $07EB, $07EC, $07ED, $07EE, $07EF
    dw $07F0

StreamTick:
    push af
    push bc
    push de
    push hl
    ld hl, wCh1Flags
    sub a
    call ChannelReadStream
    ld hl, wCh2Flags
    ld a, $01
    call ChannelReadStream
    ld hl, wCh3Flags
    ld a, $02
    call ChannelReadStream

PopAllRet:
    pop hl
    pop de
    pop bc
    pop af
    ret

ChannelReadStream:
    ldh [hChannel], a
    ld a, l
    ldh [hChannelBase], a
    ld a, h
    ldh [hChannelBase+1], a
    ld a, [hli]
    bit 7, a                          ; stopped?
    ret nz
    dec [hl]                          ; --Timer; read only when it reaches 0
    ret nz
.l44EA:
    call ReadStreamByte
    cp $E0                            ; $00-$DF: note/rest/tie -> Event, handled on the next tick
    jr nc, ChannelReadStream.l44F9
    ld hl, $0004                      ; +$04 Event
    call ChannelField
    ld [hl], a
    ret
.l44F9:
    cp $FF
    jr z, ChannelReadStream.l4513
    cp $F0                            ; $E0 tempo, $E1-$EF volume
    jp nc, DispatchCommand
    and $0F
    jr nz, ChannelReadStream.l450E
    call ReadStreamByte
    ldh [hTempo], a
    jp ChannelReadStream.l44EA
.l450E:
    ld hl, $000B
    jr StoreChannelField
.l4513:
    ld hl, $0000                      ; $FF: stop the channel, NRx2 = 0
    call ChannelField
    set 7, [hl]
    ldh a, [hChannel]
    ld e, a
    ld d, $00
    ld hl, RegStop
    add hl, de
    ld c, [hl]
    sub a
    ldh [c], a
    ret

CmdTable:
    ; $F0-$FE (the 16th slot would be the first bytes of Cmd_Octave; $FF never gets here)
    dw Cmd_Octave             ; $F0
    dw Cmd_Octave             ; $F1
    dw Cmd_Octave             ; $F2
    dw Cmd_Octave             ; $F3
    dw Cmd_Octave             ; $F4
    dw Cmd_SetNRx1            ; $F5
    dw $0000                  ; $F6  <- jumps to $0000 (reset vector): crash
    dw Cmd_Instrument         ; $F7
    dw Cmd_Wave               ; $F8
    dw Cmd_SetLoop            ; $F9
    dw Cmd_SetLoop            ; $FA
    dw Cmd_SetLoop            ; $FB
    dw Cmd_Loop               ; $FC
    dw Cmd_IfLoopDone         ; $FD
    dw Cmd_Jump               ; $FE

Cmd_Octave:
    and $0F                           ; $F0-$F4: octave 0-4
    ld hl, $0005
    jr StoreChannelField

Cmd_SetNRx1:
    call ReadStreamByte
    ld hl, $0018
    jr StoreChannelField

Cmd_SetLoop:
    and $0F                           ; $F9-$FB: loop count 1-3
    sub $08
    ld hl, $0006                      ; +$06 LoopCount

StoreChannelField:
    call ChannelField
    ld [hl], a
    jp ChannelReadStream.l44EA

Cmd_Loop:
    ld hl, $0006                      ; $FC: count 0 -> fall through; else --count and jump
    call ChannelField
    ld a, [hl]
    cp $00
    jr nz, Cmd_Loop.l4577
    call ReadStreamByte
    call ReadStreamByte
    jp ChannelReadStream.l44EA
.l4577:
    dec [hl]
    jr Cmd_Jump

Cmd_IfLoopDone:
    ld hl, $0006                      ; $FD: count 0 -> jump (last pass), else skip
    call ChannelField
    ld a, [hl]
    cp $00
    jr z, Cmd_Jump
    call ReadStreamByte
    call ReadStreamByte
    jp ChannelReadStream.l44EA

Cmd_Jump:
    ld hl, $0003                      ; +$03 Ptr+1
    call ChannelField
    call ReadStreamByte
    ld e, a
    call ReadStreamByte
    ld [hld], a
    ld [hl], e
    jp ChannelReadStream.l44EA

RegStop:
    db $12, $17, $1C, $21             ; "end of track" volume registers (NR12, NR22, NR32, NR42)

DispatchCommand:
    push af
    and $0F
    add a, a
    ld e, a
    ld d, $00
    ld hl, CmdTable
    call ReadWordAtHLDE
    push de
    pop hl
    pop af
    jp hl

ChannelField:
    push af
    push de
    ldh a, [hChannelBase]
    ld e, a
    ldh a, [hChannelBase+1]
    ld d, a
    add hl, de
    pop de
    pop af
    ret

ReadStreamByte:
    push de
    push hl
    ldh a, [hChannelBase]
    ld l, a
    ldh a, [hChannelBase+1]
    ld h, a
    ld de, $0002
    call ReadWordAtHLDE
    dec hl
    ld a, [de]
    inc de
    ld [hl], e
    inc hl
    ld [hl], d
    pop hl
    pop de
    ret

Cmd_Wave:
    xor a                             ; $F8 n: load wave n (16 bytes at WaveTable + n*16) and retrigger CH3
    ldh [rNR30], a
    call ReadStreamByte
    ld d, a
    and $0F
    swap a
    ld e, a
    ld a, d
    swap a
    and $0F
    ld d, a
    ld hl, WaveTable
    add hl, de
    ld c, $30
    ld b, $10
.l45F2:
    ld a, [hli]
    ldh [c], a
    inc c
    dec b
    jr nz, Cmd_Wave.l45F2
    ld a, $80
    ldh [rNR30], a
    ld a, [wCh3NRx4]
    or $80
    and $87
    ldh [rNR34], a
    jp ChannelReadStream.l44EA

Cmd_Instrument:
    call ReadStreamByte               ; $F7 kk iiiiii: select instrument sequence k (vol/pitch/duty/pan) = i, restart it
    ld b, a
    rlca
    rlca
    and $03
    ld e, a
    ld d, $00
    ld hl, InstrFieldTable
    add hl, de
    ld a, [hl]
    ld l, a
    ld h, $00
    call ChannelField
    ld a, b
    and $3F
    ld [hli], a
    sub a
    ld [hli], a
    inc a
    ld [hli], a
    jp ChannelReadStream.l44EA

InstrFieldTable:
    db $0C, $0F, $12, $15             ; struct offsets for $F7 kinds 0-3: VolEnv, Pitch, Duty, Pan
    db $C9, $01                       ; unused bytes

