PitchFxTable:   ; pitch effects: (ticks, signed offset) pairs, 0 = goto
    dw PitchFx0
    dw PitchFx1
    dw PitchFx2
    dw PitchFx3
    dw PitchFx4
    dw PitchFx5
    dw PitchFx6
    dw PitchFx7
    dw PitchFx8

PitchFx0:
    pfx 255, 0
    seq_goto 0

PitchFx1:
    pfx 3, 1
    pfx 3, 0
    pfx 3, -1
    pfx 3, 0
    seq_goto 0

PitchFx2:
    pfx 2, -1
    pfx 2, -2
    pfx 2, -3
    seq_goto 0

PitchFx3:
    pfx 20, 0
    pfx 3, 1
    pfx 3, 0
    seq_goto 2

PitchFx4:
    pfx 16, 0
    pfx 2, 0
    pfx 2, -1
    seq_goto 2

PitchFx5:
    pfx 20, 0
    pfx 3, 0
    pfx 3, -1
    seq_goto 2

PitchFx6:
    pfx 2, 0
    pfx 2, -1
    pfx 2, 0
    pfx 2, 1
    seq_goto 0

PitchFx7:
