WaveTable:  ; 8 CH3 waveforms
    db $DA, $C9, $B8, $A8, $68, $57, $46, $38, $DA, $C9, $B8, $A8, $68, $57, $46, $38

Wave1:
    db $00, $00, $55, $55, $AA, $AA, $FF, $FF, $00, $00, $55, $55, $AA, $AA, $FF, $FF

Wave2:
    db $FA, $52, $02, $5A, $FA, $52, $02, $5A, $FA, $52, $02, $5A, $FA, $52, $02, $5A

Wave3:
    db $01, $23, $45, $67, $89, $AB, $CD, $EF, $01, $23, $45, $67, $89, $AB, $CD, $EF

Wave4:
