CopyBytes:
    ld a, [hli]
    ld [de], a
    inc de
    dec c
    jr nz, CopyBytes
    ret

SpecialSongUpdate:
    ldh a, [hSpecialSong]             ; $FFE2 = song to play "on top" (e.g. a fanfare); the current song resumes when it stops
    cp $00
    jr z, SpecialSongUpdate.l6A72
    ldh a, [hSpecialActive]
    cp $00
    jr nz, SpecialSongUpdate.l6A69
    ldh a, [hTempo]
    ld [wSavedTempo], a
    ldh a, [hSongRequest]
    ld [wSavedSong], a
    ld a, $01
    ldh [hSpecialActive], a
    ld c, $60                         ; save all channel structs to wSavedChannels
    ld hl, wCh1Flags
    ld de, wSavedChannels
    call CopyBytes
.l6A69:
    ldh a, [hSpecialSong]
    ldh [hSongRequest], a
    sub a
    ldh [hSpecialSong], a
    ldh [hSongCurrent], a
.l6A72:
    ldh a, [hSpecialActive]
    cp $00
    jr z, SpecialSongUpdate.l6AA7
    ld a, [wCh1Flags]
    ld e, a
    ld a, [wCh2Flags]
    ld d, a
    ld a, [wCh3Flags]
    ld c, a
    ld a, $80                         ; resume when all three channels are stopped
    and c
    and d
    and e
    cp $00
    jr z, SpecialSongUpdate.l6AA7
    ld c, $60
    ld hl, wSavedChannels
    ld de, wCh1Flags
    call CopyBytes
    ld a, [wSavedTempo]
    ldh [hTempo], a
    ld a, [wSavedSong]
    ldh [hSongRequest], a
    ldh [hSongCurrent], a
    sub a
    ldh [hSpecialActive], a
.l6AA7:
    ret

SfxUpdate:
    ldh a, [hSfxRequest]              ; A = SFX id 1-36, no range check, no priority; always claims CH1 and CH4
    cp $00
    jr z, SfxUpdate.l6ADF
    dec a
    add a, a
    ld b, a
    ld e, a
    ld d, $00
    ld hl, SfxToneTable
    add hl, de
    ld a, [hli]
    ldh [hSfxTonePtr], a
    ld a, [hl]
    ldh [hSfxTonePtr+1], a
    ld a, b
    ld e, a
    ld d, $00
    ld hl, SfxNoiseTable
    add hl, de
    ld a, [hli]
    ldh [hSfxNoisePtr], a
    ld a, [hl]
    ldh [hSfxNoisePtr+1], a
    ld hl, wCh1Flags
    set 0, [hl]
    ld a, $01
    ld [wSfxNoiseOn], a
    ld [wSfxToneTimer], a
    ld [wSfxNoiseTimer], a
    sub a
    ldh [hSfxRequest], a
.l6ADF:
    ld a, [wCh1Flags]
    bit 0, a
    call nz, SfxToneStep
    ld a, [wSfxNoiseOn]
    bit 0, a
    call nz, SfxNoiseStep
    ret

SfxToneStep:
    ld hl, wSfxToneTimer
    dec [hl]
    ret nz
    ldh a, [rNR51]
    or $11
    ldh [rNR51], a
.l6AFB:
    ldh a, [hSfxTonePtr]
    ld l, a
    ldh a, [hSfxTonePtr+1]
    ld h, a
.l6B01:
    ld a, [hl]
    and $F0                           ; $En = set loop count n
    cp $E0
    jr nz, SfxToneStep.l6B10
    ld a, [hli]
    and $0F
    ld [wSfxToneCount], a
    jr SfxToneStep.l6B01
.l6B10:
    cp $F0                            ; $Fx ptr = loop while --count != 0
    jr nz, SfxToneStep.l6B2A
    ld a, [wSfxToneCount]
    dec a
    ld [wSfxToneCount], a
    inc hl
    jr z, SfxToneStep.l6B26
    ld a, [hli]
    ldh [hSfxTonePtr], a
    ld a, [hli]
    ldh [hSfxTonePtr+1], a
    jr SfxToneStep.l6AFB
.l6B26:
    inc hl
    inc hl
    jr SfxToneStep.l6B01
.l6B2A:
    ld a, [hli]                       ; duration 0 = end
    cp $00
    jr nz, SfxToneStep.l6B47
    ld hl, wCh1Flags
    res 0, [hl]
    ld c, $10
    sub a
    ldh [c], a
    inc c
    ldh a, [rNR51]                    ; CH1 removed from NR51 until the music's pan sequence steps again
    and $EE
    ldh [rNR51], a
    ld hl, wCh1NRx1                   ; restore NR11-NR14 from the CH1 struct copies
    ld de, hSfxTonePtr
    jr SfxNoiseStep.l6BB3
.l6B47:
    ld [wSfxToneTimer], a
    ld c, $10
    ld de, hSfxTonePtr
    jr SfxNoiseStep.l6BB0

SfxNoiseStep:
    ld hl, wSfxNoiseTimer
    dec [hl]
    ret nz
    ldh a, [rNR51]
    or $88
    ldh [rNR51], a
.l6B5C:
    ldh a, [hSfxNoisePtr]
    ld l, a
    ldh a, [hSfxNoisePtr+1]
    ld h, a
.l6B62:
    ld a, [hl]
    and $F0
    cp $E0
    jr nz, SfxNoiseStep.l6B71
    ld a, [hli]
    and $0F
    ld [wSfxNoiseCount], a
    jr SfxNoiseStep.l6B62
.l6B71:
    cp $F0
    jr nz, SfxNoiseStep.l6B8B
    ld a, [wSfxNoiseCount]
    dec a
    ld [wSfxNoiseCount], a
    inc hl
    jr z, SfxNoiseStep.l6B87
    ld a, [hli]
    ldh [hSfxNoisePtr], a
    ld a, [hli]
    ldh [hSfxNoisePtr+1], a
    jr SfxNoiseStep.l6B5C
.l6B87:
    inc hl
    inc hl
    jr SfxNoiseStep.l6B62
.l6B8B:
    ld a, [hli]
    cp $00
    jr nz, SfxNoiseStep.l6B9B
    sub a
    ld [wSfxNoiseOn], a
    ldh a, [rNR51]
    and $77
    ldh [rNR51], a
    ret
.l6B9B:
    ld [wSfxNoiseTimer], a            ; noise frame: NR41 = 0, NR42, NR43, NR44 = $80
    ld c, $20
    sub a
    ldh [c], a
    inc c
    ld de, hSfxNoisePtr
    ld b, $02
    call WriteRegs
    ld a, $80
    ldh [c], a
    jr SfxNoiseStep.l6BB8
.l6BB0:
    ld a, [hli]
    ldh [c], a
    inc c
.l6BB3:
    ld b, $04
    call WriteRegs
.l6BB8:
    push hl
    push de
    pop hl
    pop de
    ld [hl], e
    inc hl
    ld [hl], d
    ret

WriteRegs:
    ld a, [hli]
    ldh [c], a
    inc c
    dec b
    jr nz, WriteRegs
    ret

